body.raw:
{
  "title": "CA par région",
  "description": "Somme des montants par région",
  "datasetId": "{{datasetId}}",
  "config": {
    "query": {
      "metrics": [
        {
          "op": "sum",
          "field": "montant",
          "alias": "ca"
        },
        {
          "op": "count"
        }
      ],
      "groupBy": [
        "region"
      ],
      "orderBy": {
        "field": "ca",
        "dir": "desc"
      },
      "limit": 20
    },
    "chart": {
      "type": "bar",
      "x": "region",
      "y": [
        "ca"
      ]
    }
  }
}

{
  "title": "Pilotage ventes",
  "description": "CA par région et par mois",
  "layout": [
    {
      "id": "w1",
      "type": "analysis",
      "analysisId": "{{analysisId}}",
      "w": 2,
      "h": 2
    },
    {
      "id": "w2",
      "type": "analysis",
      "analysisId": "{{analysisId2}}",
      "w": 2,
      "h": 2
    },
    {
      "id": "w3",
      "type": "outliers",
      "datasetId": "{{datasetId}}",
      "column": "montant",
      "method": "iqr",
      "w": 4,
      "h": 3
    }
  ],
  "globalFilters": [
    {
      "id": "reg",
      "label": "Région",
      "field": "region",
      "type": "select"
    },
    {
      "id": "per",
      "label": "Période",
      "field": "date",
      "type": "date-range"
    }
  ]
}
